Here's a complete checkout page implementation with cart list, delivery address form, validation, and navigation back to the cart.

**types.ts**
```ts
export interface CartItem {
  id: string;
  name: string;
  price: number; // unit price in currency units (e.g. dollars)
  quantity: number;
  imageUrl?: string;
}

export interface DeliveryAddress {
  fullName: string;
  line1: string;
  line2: string;
  city: string;
  state: string;
  postalCode: string;
  country: string;
  phone: string;
}

export type AddressErrors = Partial<Record<keyof DeliveryAddress, string>>;
```

**CheckoutPage.tsx**
```tsx
import React, { useMemo, useState } from 'react';
import { CartItem, DeliveryAddress, AddressErrors } from './types';
import './CheckoutPage.css';

const EMPTY_ADDRESS: DeliveryAddress = {
  fullName: '',
  line1: '',
  line2: '',
  city: '',
  state: '',
  postalCode: '',
  country: '',
  phone: '',
};

const SHIPPING_FLAT_RATE = 5.99;
const TAX_RATE = 0.08;

interface CheckoutPageProps {
  items: CartItem[];
  onBackToCart: () => void;
  onPay: (address: DeliveryAddress) => void | Promise<void>;
}

function formatCurrency(amount: number): string {
  return amount.toLocaleString(undefined, {
    style: 'currency',
    currency: 'USD',
  });
}

function validateAddress(address: DeliveryAddress): AddressErrors {
  const errors: AddressErrors = {};

  if (!address.fullName.trim()) errors.fullName = 'Full name is required.';
  if (!address.line1.trim()) errors.line1 = 'Street address is required.';
  if (!address.city.trim()) errors.city = 'City is required.';
  if (!address.state.trim()) errors.state = 'State / province is required.';
  if (!address.postalCode.trim()) {
    errors.postalCode = 'Postal code is required.';
  } else if (!/^[A-Za-z0-9\- ]{3,10}$/.test(address.postalCode.trim())) {
    errors.postalCode = 'Enter a valid postal code.';
  }
  if (!address.country.trim()) errors.country = 'Country is required.';
  if (!address.phone.trim()) {
    errors.phone = 'Phone number is required.';
  } else if (!/^[0-9+()\-\s]{7,20}$/.test(address.phone.trim())) {
    errors.phone = 'Enter a valid phone number.';
  }

  return errors;
}

export default function CheckoutPage({ items, onBackToCart, onPay }: CheckoutPageProps) {
  const [address, setAddress] = useState<DeliveryAddress>(EMPTY_ADDRESS);
  const [errors, setErrors] = useState<AddressErrors>({});
  const [isSubmitting, setIsSubmitting] = useState(false);

  const subtotal = useMemo(
    () => items.reduce((sum, item) => sum + item.price * item.quantity, 0),
    [items]
  );
  const shipping = items.length > 0 ? SHIPPING_FLAT_RATE : 0;
  const tax = subtotal * TAX_RATE;
  const total = subtotal + shipping + tax;

  const handleChange = (field: keyof DeliveryAddress) => (
    e: React.ChangeEvent<HTMLInputElement>
  ) => {
    setAddress((prev) => ({ ...prev, [field]: e.target.value }));
  };

  const handlePay = async (e: React.FormEvent) => {
    e.preventDefault();

    const validationErrors = validateAddress(address);
    setErrors(validationErrors);

    if (Object.keys(validationErrors).length > 0) {
      return;
    }
    if (items.length === 0) {
      return;
    }

    setIsSubmitting(true);
    try {
      await onPay(address);
    } finally {
      setIsSubmitting(false);
    }
  };

  return (
    <div className="checkout-page">
      <header className="checkout-header">
        <button type="button" className="back-link" onClick={onBackToCart}>
          &larr; Back to cart
        </button>
        <h1>Checkout</h1>
      </header>

      <div className="checkout-layout">
        <section className="checkout-section cart-summary" aria-labelledby="cart-heading">
          <h2 id="cart-heading">Your Items</h2>

          {items.length === 0 ? (
            <p className="empty-cart">Your cart is empty.</p>
          ) : (
            <ul className="cart-item-list">
              {items.map((item) => (
                <li key={item.id} className="cart-item">
                  <img
                    className="cart-item-image"
                    src={item.imageUrl ?? 'https://via.placeholder.com/64'}
                    alt={item.name}
                  />
                  <div className="cart-item-info">
                    <span className="cart-item-name">{item.name}</span>
                    <span className="cart-item-qty">Qty: {item.quantity}</span>
                  </div>
                  <span className="cart-item-price">
                    {formatCurrency(item.price * item.quantity)}
                  </span>
                </li>
              ))}
            </ul>
          )}

          <dl className="order-totals">
            <div className="totals-row">
              <dt>Subtotal</dt>
              <dd>{formatCurrency(subtotal)}</dd>
            </div>
            <div className="totals-row">
              <dt>Shipping</dt>
              <dd>{formatCurrency(shipping)}</dd>
            </div>
            <div className="totals-row">
              <dt>Tax</dt>
              <dd>{formatCurrency(tax)}</dd>
            </div>
            <div className="totals-row totals-row-total">
              <dt>Total</dt>
              <dd>{formatCurrency(total)}</dd>
            </div>
          </dl>
        </section>

        <section className="checkout-section delivery-form" aria-labelledby="delivery-heading">
          <h2 id="delivery-heading">Delivery Address</h2>

          <form onSubmit={handlePay} noValidate>
            <div className="form-field">
              <label htmlFor="fullName">Full name</label>
              <input
                id="fullName"
                type="text"
                value={address.fullName}
                onChange={handleChange('fullName')}
                aria-invalid={!!errors.fullName}
                aria-describedby={errors.fullName ? 'fullName-error' : undefined}
              />
              {errors.fullName && (
                <span id="fullName-error" className="field-error">
                  {errors.fullName}
                </span>
              )}
            </div>

            <div className="form-field">
              <label htmlFor="line1">Address line 1</label>
              <input
                id="line1"
                type="text"
                value={address.line1}
                onChange={handleChange('line1')}
                aria-invalid={!!errors.line1}
                aria-describedby={errors.line1 ? 'line1-error' : undefined}
              />
              {errors.line1 && (
                <span id="line1-error" className="field-error">
                  {errors.line1}
                </span>
              )}
            </div>

            <div className="form-field">
              <label htmlFor="line2">Address line 2 (optional)</label>
              <input
                id="line2"
                type="text"
                value={address.line2}
                onChange={handleChange('line2')}
              />
            </div>

            <div className="form-row">
              <div className="form-field">
                <label htmlFor="city">City</label>
                <input
                  id="city"
                  type="text"
                  value={address.city}
                  onChange={handleChange('city')}
                  aria-invalid={!!errors.city}
                  aria-describedby={errors.city ? 'city-error' : undefined}
                />
                {errors.city && (
                  <span id="city-error" className="field-error">
                    {errors.city}
                  </span>
                )}
              </div>

              <div className="form-field">
                <label htmlFor="state">State / Province</label>
                <input
                  id="state"
                  type="text"
                  value={address.state}
                  onChange={handleChange('state')}
                  aria-invalid={!!errors.state}
                  aria-describedby={errors.state ? 'state-error' : undefined}
                />
                {errors.state && (
                  <span id="state-error" className="field-error">
                    {errors.state}
                  </span>
                )}
              </div>
            </div>

            <div className="form-row">
              <div className="form-field">
                <label htmlFor="postalCode">Postal code</label>
                <input
                  id="postalCode"
                  type="text"
                  value={address.postalCode}
                  onChange={handleChange('postalCode')}
                  aria-invalid={!!errors.postalCode}
                  aria-describedby={errors.postalCode ? 'postalCode-error' : undefined}
                />
                {errors.postalCode && (
                  <span id="postalCode-error" className="field-error">
                    {errors.postalCode}
                  </span>
                )}
              </div>

              <div className="form-field">
                <label htmlFor="country">Country</label>
                <input
                  id="country"
                  type="text"
                  value={address.country}
                  onChange={handleChange('country')}
                  aria-invalid={!!errors.country}
                  aria-describedby={errors.country ? 'country-error' : undefined}
                />
                {errors.country && (
                  <span id="country-error" className="field-error">
                    {errors.country}
                  </span>
                )}
              </div>
            </div>

            <div className="form-field">
              <label htmlFor="phone">Phone number</label>
              <input
                id="phone"
                type="tel"
                value={address.phone}
                onChange={handleChange('phone')}
                aria-invalid={!!errors.phone}
                aria-describedby={errors.phone ? 'phone-error' : undefined}
              />
              {errors.phone && (
                <span id="phone-error" className="field-error">
                  {errors.phone}
                </span>
              )}
            </div>

            <div className="checkout-actions">
              <button
                type="button"
                className="btn btn-secondary"
                onClick={onBackToCart}
                disabled={isSubmitting}
              >
                Back to cart
              </button>
              <button
                type="submit"
                className="btn btn-primary"
                disabled={isSubmitting || items.length === 0}
              >
                {isSubmitting ? 'Processing…' : `Pay ${formatCurrency(total)}`}
              </button>
            </div>
          </form>
        </section>
      </div>
    </div>
  );
}
```

