**Example usage (App.tsx)**
```tsx
import React, { useState } from 'react';
import CheckoutPage from './CheckoutPage';
import { CartItem, DeliveryAddress } from './types';

const sampleItems: CartItem[] = [
  { id: '1', name: 'Wireless Headphones', price: 79.99, quantity: 1 },
  { id: '2', name: 'USB-C Cable (2m)', price: 12.5, quantity: 2 },
];

export default function App() {
  const [view, setView] = useState<'cart' | 'checkout'>('checkout');

  if (view === 'cart') {
    return (
      <div>
        <h1>Cart (placeholder)</h1>
        <button onClick={() => setView('checkout')}>Proceed to checkout</button>
      </div>
    );
  }

  const handlePay = async (address: DeliveryAddress) => {
    console.log('Paying with address:', address);
    // integrate with payment API here
  };

  return (
    <CheckoutPage
      items={sampleItems}
      onBackToCart={() => setView('cart')}
      onPay={handlePay}
    />
  );
}
```

This gives you a self-contained `CheckoutPage` component (items list with per-line totals, order summary, validated delivery address form, Pay and Back-to-cart actions) that you can drop into any router/cart state — `onBackToCart` and `onPay` are the only integration points needed.
